Utilise `std::chrono::steady_clock` : il ne revient jamais en arrière, contrairement à l'horloge murale (`system_clock`), que l'utilisateur ou la synchronisation de l'heure peuvent modifier.

```cpp
struct ScopedTimer {
    const char* label;
    std::chrono::steady_clock::time_point start = std::chrono::steady_clock::now();
    ~ScopedTimer() {
        auto end = std::chrono::steady_clock::now();
        double ms = std::chrono::duration<double, std::milli>(end - start).count();
        std::printf("%s: %.2f ms\n", label, ms);
    }
};

void updatePhysics() {
    ScopedTimer t{"physics"};
    // ... every return path is timed, because the destructor always runs
}
